const cards = [...document.querySelectorAll('.card')];
const anims = cards.map((card, i) => card.animate([
  { transform: 'translateY(0px) rotate(0deg)', opacity: 1 },
  { transform: 'translateY(-10px) rotate(12deg)', opacity: 0.6, offset: 0.4, easing: 'ease-out' },
  { transform: 'translateY(0px) rotate(0deg)', opacity: 1 },
], { duration: 900, delay: i * 120, iterations: Infinity, easing: 'ease-in-out' }));
const bar = document.getElementById('bar').animate({ width: ['40px', '300px'], backgroundColor: ['#5e5ce6', '#64d2ff'] }, { duration: 1600, iterations: Infinity, direction: 'alternate', easing: 'cubic-bezier(.3,1.4,.6,1)' });
const all = [...anims, bar];
const state = document.getElementById('state');
const show = () => { state.textContent = all.map(a => a.playState[0]).join(''); };
document.getElementById('toggle').onclick = (e) => {
  const paused = all[0].playState === 'paused';
  all.forEach(a => paused ? a.play() : a.pause());
  e.target.textContent = paused ? 'Pause' : 'Play';
  Promise.all(all.map(a => a.ready)).then(show);
};
